'use client';
import {useEffect,useState} from 'react';
import {createWorkspaceRefresh} from '@/lib/workspace-refresh';
import {RevenueForecastEvidence} from './revenue-forecast-evidence';
import {readDestinationMappings,type DestinationMappings} from '@/lib/revenue-destination';
import {revenueReadiness} from '@/lib/revenue-readiness';
import {hotelRpc,usd,type HotelWorkspace} from '@/lib/pilot';
import {afterDays,type RateBook} from '@/lib/rates';
import type {PilotGatewayConnection} from '@/lib/pms-revenue-source-snapshot';
import {liveRevenueBoard,firstOccupancyForecast,pickupWindow,PICKUP_WINDOWS,RED_ROOF_SHADOW_PROPERTY,revenueFreshness,type PickupFeed} from '@/lib/revenue-live';

export function RevenueLivePanel({workspace,workspaceAt,workspaceError,tenant,property}:{workspace:HotelWorkspace;workspaceAt:string|null;workspaceError:string;tenant:string;property:string}){
 const [online,setOnline]=useState(true);
 const [destination,setDestination]=useState<DestinationMappings|null>(null);
 const [book,setBook]=useState<RateBook|null>(null),[connections,setConnections]=useState<PilotGatewayConnection[]|null>(null),[ratesAt,setRatesAt]=useState<string|null>(null),[error,setError]=useState(''),[clock,setClock]=useState(Date.now()),[busy,setBusy]=useState(false),[pickup,setPickup]=useState<PickupFeed|null>(null),[pickupError,setPickupError]=useState('');
 useEffect(()=>{
  setRatesAt(null);setDestination(null);setPickup(null);setOnline(navigator.onLine);
  const coordinator=createWorkspaceRefresh({
   visible:()=>document.visibilityState!=='hidden'&&navigator.onLine,
   read:async()=>{
    setBusy(true);
    const observedAt=new Date().toISOString();
    const history=hotelRpc<PickupFeed>('revenue_shadow_pickup',{p_tenant:tenant,p_property:property}).then(value=>{
     if(value.propertyId!==property||!Array.isArray(value.rows))throw Error('Pickup feed property mismatch.');
     return {value,error:''};
    }).catch(reason=>{
     if(reason&&typeof reason==='object'&&'code' in reason&&reason.code==='42501')throw reason;
     return {value:null,error:reason instanceof Error?reason.message:'Pickup history could not load.'};
    });
    const [rates,mappings,evidence,persisted]=await Promise.all([
     hotelRpc<RateBook>('rates',{p_tenant:tenant,p_property:property,p_start:workspace.business_date,p_end:afterDays(workspace.business_date,14)}),
     hotelRpc<PilotGatewayConnection[]>('connections',{p_tenant:tenant,p_property:property}),
     hotelRpc<unknown>('revenue_destination_mappings',{p_tenant:tenant,p_property:property}),history
    ]);
    return {rates,mappings,destination:readDestinationMappings(evidence,tenant,property),persisted,observedAt};
   },
   apply:value=>{
    setBusy(false);
    if(!navigator.onLine)return;
    setBook(value.rates);setConnections(value.mappings);setDestination(value.destination);
    setRatesAt(value.observedAt);setClock(Date.now());setError('');
    setPickup(value.persisted.value);setPickupError(value.persisted.error);
   },
   onError:reason=>{
    setBusy(false);setError(reason instanceof Error?reason.message:'PMS revenue data could not load.');
    setRatesAt(null);setDestination(null);setPickup(null);
   }
  });
  const refresh=()=>{setClock(Date.now());setOnline(navigator.onLine);coordinator.invalidate()};
  const offline=()=>{setOnline(false);setRatesAt(null);setDestination(null);setPickup(null)};
  refresh();const timer=setInterval(refresh,60000);
  window.addEventListener('focus',refresh);window.addEventListener('online',refresh);window.addEventListener('offline',offline);
  document.addEventListener('visibilitychange',refresh);
  return()=>{coordinator.dispose();clearInterval(timer);window.removeEventListener('focus',refresh);window.removeEventListener('online',refresh);window.removeEventListener('offline',offline);document.removeEventListener('visibilitychange',refresh)};
 },[tenant,property,workspace.business_date]);
 const fresh=revenueFreshness(workspaceAt,ratesAt,clock),historyFresh=pickup?.asOf!=null&&Number.isFinite(Date.parse(pickup.asOf))&&clock-Date.parse(pickup.asOf)>=0&&clock-Date.parse(pickup.asOf)<7*3600000,ready=online&&fresh.ready&&!workspaceError&&!error&&book!==null&&connections!==null&&(property!==RED_ROOF_SHADOW_PROPERTY||historyFresh);
 let board:ReturnType<typeof liveRevenueBoard>|null=null,boardError='';if(ready)try{board=liveRevenueBoard(workspace,book!,connections!,tenant,property)}catch(reason){boardError=reason instanceof Error?reason.message:'PMS revenue facts are inconsistent.'}
 const shadow=property===RED_ROOF_SHADOW_PROPERTY,expectedRows=board?board.nights.length*workspace.room_types.length:0,missingHistory=PICKUP_WINDOWS.some(days=>pickupWindow(historyFresh?pickup:null,days,expectedRows)===null);
 const gate=revenueReadiness(workspace,book,connections,pickup,online&&fresh.ready&&!workspaceError&&!error,historyFresh);
 return <div className="pilot-live-revenue"><section className="card"><div className="section-top"><div><h2>Live PMS revenue observation</h2><p>{workspace.property.name} · {workspace.property.currency} · PMS property {property}</p></div><span className={'pill '+(ready&&board?'green':'amber')}>{ready&&board?'Fresh · read only':'Actions stopped'}</span></div><p>Authenticated PMS workspace, nightly rates and saved gateway mappings. Oldest observation request started: {fresh.oldestAt?new Date(fresh.oldestAt).toLocaleString():'Unavailable'}. Refresh checks run while this view is open. Source observations older than five minutes stop recommendations.</p><p><strong>{shadow?'Red Roof shadow mode:':'Observation mode:'}</strong> Automated rate writeback and OTA delivery are disabled in this view. The existing gateway records are sandbox mappings until delivery is independently certified.</p>{!online&&<p className="pilot-error" role="alert">You are offline. Revenue suggestions are stopped until current PMS observations reload.</p>}{(error||workspaceError||boardError||pickupError)&&<p className="pilot-error" role="alert">{error||workspaceError||boardError||pickupError}</p>}{shadow&&!historyFresh&&<p className="pilot-error" role="alert">The last persisted PMS capture is missing or older than seven hours. Shadow decisions are stopped.</p>}{busy&&<p className="muted">Refreshing rates and mappings…</p>}</section>
 <section className="card"><div className="section-top"><h2>Revenue release readiness</h2><span className="pill amber">Writeback blocked</span></div><p>{gate.passed} of {gate.total} evidence checks satisfied. This report does not authorize rate changes.</p><div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Required evidence</th><th>Status</th><th>Finding / next action</th></tr></thead><tbody>{gate.gates.map(check=><tr key={check.key}><td>{check.label}</td><td>{check.passed?'Satisfied':'Blocked'}</td><td>{check.detail}</td></tr>)}</tbody></table></div></section>
 <RevenueForecastEvidence key={tenant+'|'+property} tenant={tenant} property={property} businessDate={workspace.business_date} roomTypes={workspace.room_types}/>
 <section className="card"><h2>Observed destination rate identities</h2><p>Saved OTA room metadata links the PMS BAR plans to destination BAR codes. Evidence expires after 24 hours or a source mapping or PMS plan changes. It does not certify tax calculations, restrictions, cancellation terms or successful rate delivery.</p>{destination?.observations.length?<div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>PMS plan / route</th><th>Destination room / rate code</th><th>Currency / policy version</th><th>Evidence</th></tr></thead><tbody>{destination.observations.map(row=><tr key={row.connectionId+'|'+row.pmsPlanId}><td>{book?.plans.find(plan=>plan.id===row.pmsPlanId)?.name??row.pmsPlanId}<small>{row.pmsPlanId} · v{row.pmsPlanVersion}</small><small>{row.connectionId}</small></td><td>{row.destinationPlanCode} · {row.destinationPlanName}<small>{row.destinationPropertyId} / {row.destinationRoomId}</small></td><td>{row.currency}<small>Cancellation policy version: {row.cancellationPolicyVersion??'Unavailable'}</small></td><td>{row.status.replaceAll('_',' ')}<small>Observed {new Date(row.observedAt).toLocaleString()}</small><small>Certification pending</small></td></tr>)}</tbody></table></div>:<p>No current destination identity evidence loaded.</p>}</section>
 {!board?<section className="card pilot-empty">Live revenue decisions are blocked until the PMS data and mappings load within the freshness limit.</section>:<><section className="card"><h2>Saved property, room and rate identities</h2><div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>PMS room type</th><th>PMS ID</th><th>Gateway destination ID</th><th>Active PMS plans</th></tr></thead><tbody>{workspace.room_types.map(type=><tr key={type.id}><td>{type.name}</td><td>{type.id}</td><td>{board.connections.filter(c=>c.enabled).flatMap(c=>Object.entries(c.room_types).filter(([,id])=>id===type.id).map(([id])=>c.ota_property_id+' / '+id)).join(' · ')||'Unmapped'}</td><td>{board.plans.filter(plan=>plan.room_type_id===type.id).map(plan=>plan.name+' ('+plan.id+')').join(' · ')||'None'}</td></tr>)}</tbody></table></div><p>Gateway mappings are persisted in PMS. Observed destination BAR codes are listed above. The complete rate-plan contract and delivery remain uncertified; see the exceptions below.</p></section><section className="card"><h2>Reservations, inventory, occupancy and ADR</h2><p>Current on-books values from PMS reservations and effective inventory. ADR uses booked accommodation where complete; it is not realized revenue.</p><div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Stay night</th><th>Sold</th><th>Effective rooms</th><th>Occupancy</th><th>Booked ADR</th><th>Available</th></tr></thead><tbody>{board.nights.map(row=><tr key={row.stayDate}><td>{row.stayDate}</td><td>{row.reservedUnits}</td><td>{row.effectiveUnits??'Unknown'}</td><td>{row.occupancyPercent===null?'Unknown':row.occupancyPercent+'%'}</td><td>{row.adrMinor===null?'Unknown':usd(row.adrMinor)}</td><td>{row.availableUnits??'Unknown'}</td></tr>)}</tbody></table></div><p>ADR uses stay totals allocated evenly by night; variable nightly quoted prices are not reconstructed. Cancellation effects are reflected in current on-books inventory. Cancellation and booking timestamps for historical pickup are not available in this feed.</p></section><section className="card"><h2>Pickup and demand forecast</h2><div className="pilot-report-totals">{PICKUP_WINDOWS.map(window=><div key={window}><span>{window}-day pickup</span><strong>{(()=>{const result=pickupWindow(historyFresh?pickup:null,window,expectedRows);return result?`${result.roomNights>=0?'+':''}${result.roomNights} rooms`:'Unavailable'})()}</strong></div>)}</div><div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Stay night</th><th>On books</th><th>First occupancy forecast</th><th>Confidence and basis</th></tr></thead><tbody>{board.nights.map(night=>{const forecast=firstOccupancyForecast(historyFresh?pickup:null,night.stayDate,workspace.business_date,night.reservedUnits,night.effectiveUnits,workspace.room_types.map(type=>type.id));return <tr key={night.stayDate}><td>{night.stayDate}</td><td>{night.reservedUnits}</td><td>{forecast?forecast.projectedUnits+' rooms · '+forecast.projectedOccupancyPercent+'%':'Awaiting seven-day history'}</td><td>{forecast?<>{forecast.confidence}<small>{forecast.explanation}</small></>:'No validated pickup baseline yet'}</td></tr>})}</tbody></table></div><p>Last persisted capture: {pickup?.asOf?new Date(pickup.asOf).toLocaleString():'Unavailable'} · {historyFresh?'Capture current':'Capture delayed'}. Six-hour PMS captures have begun for Red Roof. Each window becomes available only after a matching baseline exists for every room and stay date. Missing history is never zero pickup. The first pace projection appears when seven-day history exists. It remains unvalidated and is never used to write rates.</p>{pickupError&&<p className="pilot-error" role="alert">Pickup feed: {pickupError}</p>}</section><section className="card"><h2>Shadow rate suggestions</h2><p>Deterministic occupancy previews with conservative guardrails. Confidence is low because booking pickup, events, competitor prices and forecast validation are missing. No save or publish action is offered.</p><div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Night / plan</th><th>Current</th><th>Preview</th><th>Confidence</th><th>Reason</th></tr></thead><tbody>{board.recommendations.slice(0,30).map(item=><tr key={item.key}><td>{item.stayDate}<small>{item.plan}</small></td><td>{usd(item.current)}</td><td>{usd(item.suggested)}</td><td>{item.confidence}</td><td>{item.explanation[0]}</td></tr>)}</tbody></table></div>{board.recommendations.length>30&&<p>Showing the first 30 of {board.recommendations.length} previews.</p>}</section><section className="card"><h2>Supervisor exception queue <span className="count">{board.exceptions.length+(missingHistory?1:0)+(!historyFresh?1:0)}</span></h2><p>Prioritized for this property. Use Revenue supervisor in the menu to claim and track shared reviews across authorized properties. A single-session database queue check passed with 500 properties. Concurrent use and live portfolio operation remain unvalidated.</p>{!historyFresh&&<div className="pilot-list-row"><div><strong>Snapshot capture is delayed</strong><small>Check the scheduled PMS job. Shadow recommendations cannot be promoted while evidence is stale.</small></div><span className="pill amber">Critical</span></div>}{missingHistory&&<div className="pilot-list-row"><div><strong>Pickup history or forecast unavailable</strong><small>Wait for complete matching 1/3/7/14/30-day baselines and validate a forecast.</small></div><span className="pill amber">Attention</span></div>}{board.exceptions.slice(0,100).map(item=><div className="pilot-list-row" key={item.key}><div><strong>{item.title}</strong><small>{item.detail}</small></div><span className={'pill '+(item.priority==='critical'?'amber':'gray')}>{item.priority}</span></div>)}{board.exceptions.length>100&&<p>Showing 100 exceptions. Narrow the date range in Rates &amp; plans to investigate further.</p>}</section></>}
 </div>;
}
